mapper.sql:
SELECT contract_no, MAX(company_id) AS company_id, MAX(company_name) AS company_name, CASE WHEN COUNT(DISTINCT NULLIF(department_code,''))=1 THEN MAX(department_id) END AS department_id, CASE WHEN COUNT(DISTINCT NULLIF(department_code,''))=1 THEN MAX(NULLIF(department_code,'')) END AS department_code, CASE WHEN COUNT(DISTINCT NULLIF(department_code,''))=1 THEN MAX(NULLIF(department_name,'')) END AS department_name FROM ( SELECT contract_no,company_id,company_code,company_name,NULL AS department_id,department_code,department_name FROM com_contract WHERE tenant_id=#{query.tenantId} AND deleted=0
UNION ALL SELECT contract_no,company_id,company_code,company_name,department_id,department_code,department_name FROM com_shipment_contract_reference WHERE tenant_id=#{query.tenantId} AND deleted=0
) ownership WHERE contract_no IS NOT NULL AND contract_no <> '' GROUP BY contract_no HAVING COUNT(DISTINCT company_id)=1 AND COUNT(DISTINCT NULLIF(company_code,''))=1 AND SUM(CASE WHEN company_code IS NULL OR company_code='' THEN 1 ELSE 0 END)=0

mapper.select:
SELECT f.contract_no FROM () f

  WHERE 
    (f.company_id=#{grant.companyId}

      AND (f.department_id=#{grant.departmentId}
        OR CAST(f.department_code AS BINARY)=CAST(#{grant.departmentCode} AS BINARY))
    )

WHERE 1=0

SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND master_source_system = #{query.sourceSystem}
  AND master_source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT c.* FROM com_contract c WHERE c.tenant_id = #{query.tenantId} AND c.deleted = 0 AND (
CAST(c.company_code AS BINARY) IN CAST(#{companyCode} AS BINARY)
OR
EXISTS (SELECT 1 FROM com_project_contract_relation pcr WHERE pcr.tenant_id = c.tenant_id AND pcr.contract_id = c.id AND pcr.deleted = 0 AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL AND pcr.project_id IN #{projectId})
)
AND contract_no LIKE CONCAT('%', #{query.contractNo}, '%')
AND CAST(company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND contract_type = #{query.contractType}
AND (customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%') OR customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%'))
AND master_source_system = #{query.sourceSystem}
AND status = #{query.status}
ORDER BY c.contract_no, c.id LIMIT #{query.offset}, #{query.limit}

SELECT COUNT(*) FROM com_contract c WHERE c.tenant_id = #{query.tenantId} AND c.deleted = 0 AND (
CAST(c.company_code AS BINARY) IN CAST(#{companyCode} AS BINARY)
OR
EXISTS (SELECT 1 FROM com_project_contract_relation pcr WHERE pcr.tenant_id = c.tenant_id AND pcr.contract_id = c.id AND pcr.deleted = 0 AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL AND pcr.project_id IN #{projectId})
)
AND contract_no LIKE CONCAT('%', #{query.contractNo}, '%')
AND CAST(company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND contract_type = #{query.contractType}
AND (customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%') OR customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%'))
AND master_source_system = #{query.sourceSystem}
AND status = #{query.status}

SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.contractId}
  AND deleted = 0
FOR UPDATE
